import type { MetadataRoute } from "next";

/**
 * /sitemap.xml — generated by Next.js from this file.
 * Public pages + every published event page (/events/<slug>), refreshed hourly from the API.
 * Private areas (dashboards, login, invite/ticket links, payment pages) are left out on purpose.
 */

const SITE = (process.env.NEXT_PUBLIC_SITE_URL || "https://www.tropica.nyc").replace(/\/+$/, "");
const API = (process.env.NEXT_PUBLIC_API_URL || "https://fishndropbackend.nextbusinesssolution.com/api").replace(/\/+$/, "");

const STATIC_PAGES: { path: string; priority: number; changeFrequency: MetadataRoute.Sitemap[number]["changeFrequency"] }[] = [
  { path: "/", priority: 1.0, changeFrequency: "weekly" },
  { path: "/book-venue", priority: 0.9, changeFrequency: "weekly" },
  { path: "/book-table", priority: 0.9, changeFrequency: "weekly" },
  { path: "/our-dining", priority: 0.8, changeFrequency: "monthly" },
  { path: "/events", priority: 0.8, changeFrequency: "daily" },
  { path: "/gallery", priority: 0.7, changeFrequency: "monthly" },
  { path: "/about", priority: 0.7, changeFrequency: "monthly" },
  { path: "/book-tour", priority: 0.6, changeFrequency: "monthly" },
  { path: "/blog", priority: 0.6, changeFrequency: "weekly" },
  { path: "/partner", priority: 0.4, changeFrequency: "monthly" },
  { path: "/terms", priority: 0.2, changeFrequency: "yearly" },
  { path: "/privacy", priority: 0.2, changeFrequency: "yearly" }
];

const getEventEntries = async (): Promise<MetadataRoute.Sitemap> => {
  try {
    const res = await fetch(`${API}/events/public`, { next: { revalidate: 3600 } });
    if (!res.ok) return [];
    const json = await res.json();
    const events: { slug?: string; updatedAt?: string }[] = json.events || json.data || [];
    return events
      .filter((e) => e.slug)
      .map((e) => ({
        url: `${SITE}/events/${encodeURIComponent(e.slug as string)}/`,
        lastModified: e.updatedAt ? new Date(e.updatedAt) : new Date(),
        changeFrequency: "daily" as const,
        priority: 0.7
      }));
  } catch {
    // API down → still serve the static part of the sitemap
    return [];
  }
};

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const now = new Date();
  const pages = STATIC_PAGES.map((p) => ({
    // next.config has trailingSlash: true → the real URL ends in "/" (no-slash versions 308-redirect)
    url: `${SITE}${p.path === "/" ? "/" : `${p.path}/`}`,
    lastModified: now,
    changeFrequency: p.changeFrequency,
    priority: p.priority
  }));
  return [...pages, ...(await getEventEntries())];
}
